int logfmt_parse_multi(const char *in, char **keys, char **vals, int max_pairs) {
    int count = 0;
    const char *pair_start = in;

    while (count < max_pairs) {
        const char *eq = strchr(pair_start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair_start);
        keys[count] = malloc(klen + 1);
        strncpy(keys[count], pair_start, klen);
        keys[count][klen] = '\0';

        const char *quote = strchr(eq, '"');
        if (quote) {
            const char *end_quote = strchr(quote + 1, '"');
            if (end_quote) {
                size_t vlen = (size_t)(end_quote - quote - 1);
                vals[count] = malloc(vlen + 1);
                strncpy(vals[count], quote + 1, vlen);
                vals[count][vlen] = '\0';
                pair_start = end_quote + 1;
                continue;
            }
        }

        size_t vlen = (size_t)(strlen(eq) - 1);
        vals[count] = malloc(vlen + 1);
        strncpy(vals[count], eq + 1, vlen);
        vals[count][vlen] = '\0';
        pair_start = strchr(eq, ' ') + 1;
        count++;
    }

    return count;
}

